Here is the commit message:
RDMA/mana_ib: Ignore optional access flags for MRs

Ignore optional ib_access_flags when an MR is created.

Fixes: 0266a177631d ("RDMA/mana_ib: Add a driver for Microsoft Azure Network Adapter")
Signed-off-by: Konstantin Taranov <kotaranov@microsoft.com>
Link: https://lore.kernel.org/r/1717575368-14879-1-git-send-email-kotaranov@linux.microsoft.com
Signed-off-by: Leon Romanovsky <leon@kernel.org>

Here is the root cause:
The bug arises from the inclusion of optional access flags in the `access_flags` variable when creating a memory region (MR). These optional flags were not intended to be considered, leading to potential invalid configurations and errors during MR registration. The patch corrects this by explicitly clearing the optional flags before validating the access flags.

Here is the patch:

 struct ib_mr *mana_ib_reg_user_mr(struct ib_pd *ibpd, u64 start, u64 length,
 				  u64 iova, int access_flags,
 				  struct ib_udata *udata)
 {
 	struct mana_ib_pd *pd = container_of(ibpd, struct mana_ib_pd, ibpd);
 	struct gdma_create_mr_params mr_params = {};
 	struct ib_device *ibdev = ibpd->device;
 	struct mana_ib_dev *dev;
 	struct mana_ib_mr *mr;
 	u64 dma_region_handle;
 	int err;

 	dev = container_of(ibdev, struct mana_ib_dev, ib_dev);

 	ibdev_dbg(ibdev,
 		  "start 0x%llx, iova 0x%llx length 0x%llx access_flags 0x%x",
 		  start, iova, length, access_flags);

+	access_flags &= ~IB_ACCESS_OPTIONAL;
 	if (access_flags & ~VALID_MR_FLAGS)
 		return ERR_PTR(-EINVAL);

 	mr = kzalloc(sizeof(*mr), GFP_KERNEL);
 	if (!mr)
 		return ERR_PTR(-ENOMEM);

 	mr->umem = ib_umem_get(ibdev, start, length, access_flags);
 	if (IS_ERR(mr->umem)) {
 		err = PTR_ERR(mr->umem);
 		ibdev_dbg(ibdev,
 			  "Failed to get umem for register user-mr, %d\n", err);
 		goto err_free;
 	}

 	err = mana_ib_create_dma_region(dev, mr->umem, &dma_region_handle, iova);
 	if (err) {
 		ibdev_dbg(ibdev, "Failed create dma region for user-mr, %d\n",
 			  err);
 		goto err_umem;
 	}

 	ibdev_dbg(ibdev,
 		  "created dma region for user-mr 0x%llx\n",
 		  dma_region_handle);

 	mr_params.pd_handle = pd->pd_handle;
 	mr_params.mr_type = GDMA_MR_TYPE_GVA;
 	mr_params.gva.dma_region_handle = dma_region_handle;
 	mr_params.gva.virtual_address = iova;
 	mr_params.gva.access_flags =
 		mana_ib_verbs_to_gdma_access_flags(access_flags);

 	err = mana_ib_gd_create_mr(dev, mr, &mr_params);
 	if (err)
 		goto err_dma_region;

 	/*
 	 * There is no need to keep track of dma_region_handle after MR is
 	 * successfully created. The dma_region_handle is tracked in the PF
 	 * as part of the lifecycle of this MR.
 	 */

 	return &mr->ibmr;

 err_dma_region:
 	mana_gd_destroy_dma_region(mdev_to_gc(dev), dma_region_handle);

 err_umem:
 	ib_umem_release(mr->umem);

 err_free:
 	kfree(mr);
 	return ERR_PTR(err);
 }



